    if (gen.status !== 0) {
      harnessError('prisma generate failed: ' + ((gen.stderr||'')+(gen.stdout||'')));
    } else {
      const test = cp.spawnSync(winx ? 'npx.cmd' : 'npx', ['vitest', 'run', RUN_PATH, '--testTimeout=15000'], { env: env, encoding: 'utf8', shell: winx, timeout: 120000 });
      const out = (test.stdout || '') + (test.stderr || '');
